@custom-variant dark (&:where(.dark, .dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--background);
  --color-card-foreground: var(--foreground);
  --color-popover: var(--background);
  --color-popover-foreground: var(--foreground);
  --color-primary: var(--foreground);
  --color-primary-foreground: var(--background);
  --color-secondary: var(--muted);
  --color-secondary-foreground: var(--foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--muted);
  --color-accent-foreground: var(--foreground);
  --color-destructive: #ef4444;
  --color-border: var(--border);
  --color-input: var(--border);
  --color-ring: var(--foreground);
  --color-brand: #f472b6;
  --color-brand-secondary: #db2777;
  --color-smooth-500: #b5b5b5;
  --color-smooth-900: #262626;
  --color-blue: #70c4db;
  --color-blue-fg: #083344;
  --color-blue-hover: #40a1bd;
  --color-green: #8bd6a3;
  --color-green-fg: #123b20;
  --color-green-hover: #4caf70;
  --color-amber: #f7cb78;
  --color-amber-fg: #713f12;
  --color-amber-hover: #e7ab49;
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --animate-marquee: marquee var(--duration, 30s) linear infinite;
  --animate-marquee-vertical: marquee-vertical var(--duration, 30s) linear infinite;
  --animate-rippling: rippling var(--duration, 0.6s) ease-out;
  --animate-spin-around: spin-around calc(var(--speed) * 2) infinite linear;
  --animate-shimmer-slide: shimmer-slide var(--speed) ease-in-out infinite alternate;
  --animate-background-position-spin: background-position-spin 3000ms infinite alternate;
  @keyframes rippling {
    0% {
      opacity: 1;
    }
    100% {
      transform: scale(2);
      opacity: 0;
    }
  }
  @keyframes spin-around {
    0% {
      transform: translateZ(0) rotate(0);
    }
    15%,
    35% {
      transform: translateZ(0) rotate(90deg);
    }
    65%,
    85% {
      transform: translateZ(0) rotate(270deg);
    }
    100% {
      transform: translateZ(0) rotate(360deg);
    }
  }
  @keyframes shimmer-slide {
    to {
      transform: translate(calc(100cqw - 100%), 0);
    }
  }
  @keyframes background-position-spin {
    0% {
      background-position: top center;
    }
    100% {
      background-position: bottom center;
    }
  }
  --animate-meteor: meteor 5s linear infinite;
  --animate-ripple: ripple var(--duration, 2s) ease calc(var(--i, 0) * 0.2s) infinite;
  @keyframes meteor {
    0% {
      transform: rotate(var(--angle)) translateX(0);
      opacity: 1;
    }
    70% {
      opacity: 1;
    }
    100% {
      transform: rotate(var(--angle)) translateX(-500px);
      opacity: 0;
    }
  }
  @keyframes ripple {
    0%,
    100% {
      transform: translate(-50%, -50%) scale(1);
    }
    50% {
      transform: translate(-50%, -50%) scale(0.9);
    }
  }
  @keyframes marquee {
    to {
      transform: translateX(calc(-100% - var(--gap, 1rem)));
    }
  }
  @keyframes marquee-vertical {
    to {
      transform: translateY(calc(-100% - var(--gap, 1rem)));
    }
  }
}

:root {
  --background: #fafafa;
  --foreground: #18181b;
  --muted: #f0f0f1;
  --muted-foreground: #71717a;
  --border: #e4e4e7;
}
.dark {
  --background: #101014;
  --foreground: #fafafa;
  --muted: #252529;
  --muted-foreground: #a1a1aa;
  --border: #303036;
  color-scheme: dark;
}
@layer base {
  * {
    border-color: var(--border);
  }
  body {
    margin: 0;
    background: var(--background);
    color: var(--foreground);
    font-family: Arial, Helvetica, sans-serif;
  }
  button,
  a {
    -webkit-tap-highlight-color: transparent;
  }
  button:not(:disabled),
  [role="button"] {
    cursor: pointer;
  }
  :focus-visible {
    outline: 2px solid #0088ff;
    outline-offset: 4px;
  }
}
